    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(x for x in counts if x != bg)
    # Detect a rectangular frame with exactly one missing perimeter cell.
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    perimeter = set()
    for c in range(c0,c1+1):
        perimeter.add((r0,c)); perimeter.add((r1,c))
    for r in range(r0,r1+1):
        perimeter.add((r,c0)); perimeter.add((r,c1))
    if len(pts) == len(perimeter)-1 and all(grid[r][c] in (fg,bg) for r,c in perimeter):
        for r,c in perimeter:
            if grid[r][c] == bg:
                out[r][c] = 2
    return out
